return {["pre"]={{["speaker"]="shion",["portrait"]="shion08",["line"]=1,["text"]="「啊哈—好棒呢～这里都快被令人舒服的气味充满了……」",["rows"]={"「啊哈—好棒呢～这里都快被令人舒服的气味","充满了……」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=2,["text"]="「你是……幽幽子？」",["rows"]={"「你是……幽幽子？」"}},{["speaker"]="shion",["portrait"]="shion04",["line"]=3,["text"]="「是小死宛哦♪ 你好啊，美味的人类♪」",["rows"]={"「是小死宛哦♪ 你好啊，美味的人类♪」"}},{["speaker"]="shion",["portrait"]="shion08",["line"]=4,["text"]="「你是来陪我玩的吗？」",["rows"]={"「你是来陪我玩的吗？」"}},{["speaker"]="kaguya",["portrait"]="kaguya13",["line"]=5,["text"]="「紫苑？我记得紫苑可是蓝色头发的哦。而且每天都愁眉苦脸的。」",["rows"]={"「紫苑？我记得紫苑可是蓝色头发的哦。而且","每天都愁眉苦脸的。」"}},{["speaker"]="shion",["portrait"]="shion04",["line"]=6,["text"]="「小死宛才不会愁眉苦脸哟—」",["rows"]={"「小死宛才不会愁眉苦脸哟—」"}},{["speaker"]="shion",["portrait"]="shion06",["line"]=7,["text"]="「这里的气息♪ 如此令人愉悦♪ 」",["rows"]={"「这里的气息♪ 如此令人愉悦♪ 」"}},{["speaker"]="kaguya",["portrait"]="kaguya7",["line"]=8,["text"]="「据我所知，幽灵明明是最纯洁的……然而这家伙竟然正在疯狂吞噬身边的污秽！」",["rows"]={"「据我所知，幽灵明明是最纯洁的……然而这","家伙竟然正在疯狂吞噬身边的污秽！」"}},{["speaker"]="shion",["portrait"]="shion08",["line"]=9,["text"]="「不仅是生命力，我连死灵也能一起吸收掉哦~」",["rows"]={"「不仅是生命力，我连死灵也能一起吸收掉哦","~」"}},{["speaker"]="kaguya",["portrait"]="kaguya7",["line"]=10,["text"]="「这下白玉文明恐怕是凶多吉少了……」",["rows"]={"「这下白玉文明恐怕是凶多吉少了……」"}},{["speaker"]="shion",["portrait"]="shion07",["line"]=11,["text"]="「我可以让你也从永生的桎梏中解放哦」",["rows"]={"「我可以让你也从永生的桎梏中解放哦」"}},{["speaker"]="shion",["portrait"]="shion08",["line"]=12,["text"]="「只要让我尝一口你的灵魂♪ 」",["rows"]={"「只要让我尝一口你的灵魂♪ 」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=13,["text"]="「我也要死吗……」",["rows"]={"「我也要死吗……」"}},{["speaker"]="shion",["portrait"]="shion07",["line"]=14,["text"]="「你以为还能回去吗？」",["rows"]={"「你以为还能回去吗？」"}},{["speaker"]="shion",["portrait"]="shion06",["line"]=15,["text"]="「一闻到你的气味，就想好好品尝一番了♪」",["rows"]={"「一闻到你的气味，就想好好品尝一番了♪」"}},{["speaker"]="kaguya",["portrait"]="kaguya21",["line"]=16,["text"]="「吃你个头，幽灵就该去吃线香」",["rows"]={"「吃你个头，幽灵就该去吃线香」"}},{["speaker"]="shion",["portrait"]="shion04",["line"]=17,["text"]="「让我把你从生的苦痛中解放♪ 将你的一切，吞噬殆尽！」",["rows"]={"「让我把你从生的苦痛中解放♪ 将你的一","切，吞噬殆尽！」"}}},["post"]={{["speaker"]="shion",["portrait"]="shion03",["line"]=1,["text"]="「啊，好强大的对手♪」",["rows"]={"「啊，好强大的对手♪」"}},{["speaker"]="shion",["portrait"]="shion03",["line"]=2,["text"]="「虽然没有阿玄那么厉害，但还是输了呢—」",["rows"]={"「虽然没有阿玄那么厉害，但还是输了呢—」"}},{["speaker"]="kaguya",["portrait"]="kaguya11",["line"]=3,["text"]="「咦，竟然没有恢复正常？」",["rows"]={"「咦，竟然没有恢复正常？」"}},{["speaker"]="shion",["portrait"]="shion07",["line"]=4,["text"]="「这个身体的主人，是自愿被我凭依的哟♪」",["rows"]={"「这个身体的主人，是自愿被我凭依的哟♪」"}},{["speaker"]="shion",["portrait"]="shion08",["line"]=5,["text"]="「我是来自无现里的小死宛♪」",["rows"]={"「我是来自无现里的小死宛♪」"}},{["speaker"]="kaguya",["portrait"]="kaguya5",["line"]=6,["text"]="「无现里？」",["rows"]={"「无现里？」"}},{["speaker"]="shion",["portrait"]="shion04",["line"]=7,["text"]="「对哦—」",["rows"]={"「对哦—」"}},{["speaker"]="shion",["portrait"]="shion08",["line"]=8,["text"]="「有一天，我远远闻到这里散发着食物的香气♪ 所以我暂时离开阿玄，凭依到这个世界的居民身上来玩—」",["rows"]={"「有一天，我远远闻到这里散发着食物的香","气♪ 所以我暂时离开阿玄，凭依到这个世界"}},{["speaker"]="shion",["portrait"]="shion08",["line"]=8,["text"]="「有一天，我远远闻到这里散发着食物的香气♪ 所以我暂时离开阿玄，凭依到这个世界的居民身上来玩—」",["rows"]={"的居民身上来玩—」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=9,["text"]="「那小死宛知道这些气息的源头在哪里吗？」",["rows"]={"「那小死宛知道这些气息的源头在哪里吗？」"}},{["speaker"]="shion",["portrait"]="shion07",["line"]=10,["text"]="「哼～宛宛不知道哦—不过那个人好像和我有着同样的气味~」",["rows"]={"「哼～宛宛不知道哦—不过那个人好像和我有","着同样的气味~」"}},{["speaker"]="shion",["portrait"]="shion03",["line"]=11,["text"]="「诞生自无数生命与个体的聚集之中—」",["rows"]={"「诞生自无数生命与个体的聚集之中—」"}},{["speaker"]="kaguya",["portrait"]="kaguya1",["line"]=12,["text"]="「原来如此……」",["rows"]={"「原来如此……」"}},{["speaker"]="shion",["portrait"]="shion08",["line"]=13,["text"]="「既然已经输了，那宛宛就要回去找阿玄了哦—」",["rows"]={"「既然已经输了，那宛宛就要回去找阿玄了","哦—」"}},{["speaker"]="shion",["portrait"]="shion06",["line"]=14,["text"]="「再见~这位永远在追逐着生死的公主♪」",["rows"]={"「再见~这位永远在追逐着生死的公主♪」"}},{["speaker"]="kaguya",["portrait"]="kaguya11",["line"]=15,["text"]="「欸？这是什么意思……」",["rows"]={"「欸？这是什么意思……」"}}